"""Finite root systems generated by exact simple reflections."""
from .cartan_type import CartanType


class RootSystem:
    def __init__(self,cartantype):
        self.cartan_type = CartanType(cartantype)

    def __repr__(self):
        return 'RootSystem(%r)' % str(self.cartan_type)

    def simple_roots(self):
        return {i:self.cartan_type.simple_root(i) for i in range(1,self.cartan_type.rank()+1)}

    def all_roots(self):
        roots = self.cartan_type.positive_roots()
        count = len(roots)
        roots.update({i+count:[-v for v in root] for i,root in list(roots.items())})
        return roots

    def root_space(self):
        return ' + '.join('alpha[%s]' % i for i in range(1,self.cartan_type.rank()+1))

    def add_simple_roots(self,root1,root2):
        return [a+b for a,b in zip(self.cartan_type.simple_root(root1),self.cartan_type.simple_root(root2))]

    def add_as_roots(self,root1,root2):
        dimension = self.cartan_type.dimension()
        if len(root1) != dimension or len(root2) != dimension:
            raise ValueError('root dimension does not match the ambient space')
        roots = list(self.all_roots().values())
        if list(root1) not in roots or list(root2) not in roots:
            raise ValueError('arguments must be roots of this root system')
        result = [a+b for a,b in zip(root1,root2)]
        return result if result in roots else 'The sum of these two roots is not a root'

    def cartan_matrix(self):
        return self.cartan_type.cartan_matrix()

    def dynkin_diagram(self):
        return self.cartan_type.dynkin_diagram()
